import { readdirSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const v2Dir = resolve(here, '../src/proto/polycentric/v2');
const outFile = resolve(here, '../src/proto/v2.ts');

const modules = readdirSync(v2Dir)
  .filter((f) => f.endsWith('.ts'))
  .map((f) => f.slice(0, -'.ts'.length))
  .sort();

const contents = [
  '// Generated by scripts/generate-proto-barrel.mjs — do not edit.',
  '// Re-exports the generated protobuf-ts modules as the `v2` namespace.',
  '',
  ...modules.map((m) => `export * from './polycentric/v2/${m}';`),
  '',
].join('\n');

writeFileSync(outFile, contents);
console.log(`Wrote ${outFile} (${modules.length} modules)`);
